3	import { useEffect, useRef, useState } from "react";
4	
5	export interface LiveMetrics {
6	  tokens_saved_today: number;
7	  events_today: number;
8	  active_sessions: number;
9	  timestamp: number;
10	}
11	
12	const WS_URL =
13	  process.env.NEXT_PUBLIC_WS_URL || "ws://localhost:8080/v1/ws";
14	const TENANT_ID = process.env.NEXT_PUBLIC_TENANT_ID || "";
15	
16	export function useLiveMetrics() {
17	  const [metrics, setMetrics] = useState<LiveMetrics | null>(null);
18	  const [connected, setConnected] = useState(false);
19	  const wsRef = useRef<WebSocket | null>(null);
20	  const retriesRef = useRef(0);
21	  const maxRetries = 10;
22	
23	  useEffect(() => {
24	    function connect() {
25	      if (wsRef.current?.readyState === WebSocket.OPEN) return;
26	
27	      const url = `${WS_URL}?tenant_id=${TENANT_ID}`;
28	      const ws = new WebSocket(url);
29	      wsRef.current = ws;
30	
31	      ws.onopen = () => {
32	        setConnected(true);
33	        retriesRef.current = 0;
34	      };
35	
36	      ws.onmessage = (event) => {
37	        try {
38	          const data = JSON.parse(event.data) as LiveMetrics;
39	          setMetrics((prev) => {
40	            if (!prev) return data;
41	            return {
42	              tokens_saved_today:
43	                prev.tokens_saved_today + data.tokens_saved_today,
44	              events_today: prev.events_today + data.events_today,
45	              active_sessions: data.active_sessions || prev.active_sessions,
46	              timestamp: data.timestamp,
47	            };
48	          });
49	        } catch {
50	          // ignore malformed messages
51	        }
52	      };
53	
54	      ws.onclose = () => {
55	        setConnected(false);
56	        wsRef.current = null;
57	        if (retriesRef.current < maxRetries) {
58	          const delay = Math.min(1000 * 2 ** retriesRef.current, 30000);
59	          retriesRef.current++;
60	          setTimeout(connect, delay);
61	        }
62	      };
63	
64	      ws.onerror = () => {
65	        ws.close();
66	      };
67	    }
68	
69	    connect();
70	    return () => {
71	      wsRef.current?.close();
72	    };
73	  }, []);
74	
75	  return { metrics, connected };
76	}
